module fsm (input wire X, Y, CLK, output reg Z); 
 reg [1:0] state; 
 parameter A = 2'b00; 
 parameter B = 2'b01; 
 parameter C = 2'b10; 
 parameter D = 2'b11; initial begin 
 state <= A; 
 end 
 always @(posedge CLK or negedge reset) begin if (!reset) begin state <= A; end else begin case (state) A: begin if (X&& (~Y)) state <= B; else if ((~X) && (~Y)) state <= A; else if ((~X) && Y) state <= D; else state <= C; end B: begin if ((~X) && (~Y)) state <= A; else if (X && Y) state <= C; end C: begin if (X && Y) state <= C; end D: begin if ((~X) && (~Y)) state <= A; end endcase end end assign Z = (state == C); endmodule

