module fsm_one_hot (input clk, input x, input y, output reg z, output reg [3:0] state);
  // State encoding
  parameter A = 4'b0001, B = 4'b0010, C = 4'b0100, D = 4'b1000;

  // State transition and output logic
  always @(posedge clk) begin
    case (state)
      A: begin
        z <= 0;
        case ({x, y})
          2'b10: state <= B;
          2'b01: state <= D;
          default: state <= A;
        endcase
      end
      B: begin
        z <= 0;
        case ({x, y})
          2'b00: state <= B;
          2'b11: state <= C;
          default: state <= A;
        endcase
      end
      C: begin
        z <= 1;
        case ({x, y})
          2'b11: state <= C;
          default: state <= A;
        endcase
      end
      D: begin
        z <= 0;
        case ({x, y})
          2'b00: state <= D;
          2'b11: state <= A;
          default: state <= A;
        endcase
      end
      default: state <= A;
    endcase
  end

  // Initial state
  initial begin
    state <= A;
  end
endmodule
